#include "lzfinal_entropy.h"
#include <bits/stdc++.h>
#include <immintrin.h>
using namespace std;
int main(int argc,char**argv){int cap=argc>1?atoi(argv[1]):6144;auto rd=[](FILE*f){uint32_t x;fread(&x,4,1,f);return x;};FILE*f=fopen("/work/analysis_repair.bin","rb");uint32_t base=rd(f),nr=rd(f),nt=rd(f);for(int i=0;i<base;i++){unsigned n=rd(f);fseek(f,n,SEEK_CUR);}vector<pair<uint32_t,uint32_t>>r(nr);fread(r.data(),8,nr,f);fclose(f);string stem="/work/lzexp_tok"+to_string(cap);f=fopen((stem+"_seq.bin").c_str(),"rb");fseek(f,0,2);int n=ftell(f)/4;rewind(f);vector<uint32_t>seq(n);fread(seq.data(),4,n,f);fclose(f);f=fopen((argc>2?string(argv[2]):"/work/lzexp_dp"+to_string(cap)+"_matches.bin").c_str(),"rb");fseek(f,0,2);int nm=ftell(f)/12;rewind(f);vector<array<int,3>>matches(nm);fread(matches.data(),12,nm,f);fclose(f);vector<uint16_t>lc,ml,ll,ol;BitsOut bits;unsigned pos=0;for(auto m:matches){unsigned gap=m[0]-pos;assert(gap<65536&&m[1]<65536);ll.push_back(gap);for(;pos<m[0];pos++)lc.push_back(seq[pos]);ml.push_back(m[1]);unsigned k=31-__builtin_clz(m[2]);ol.push_back(k);bits.put(m[2]-(1u<<k),k);pos+=m[1];}ll.push_back(n-pos);for(;pos<n;pos++)lc.push_back(seq[pos]);bits.finish();bits.v.resize(bits.v.size()+8);
vector<vector<uint8_t>>streams={ans16_encode(lc,argc>3?atoi(argv[3]):15),ans16_encode(ml,12),ans16_encode(ll,12),ans16_encode(ol,12),bits.v};vector<uint16_t> dl,dh;for(int i=0;i<cap-256;i++)for(auto v:{r[i].first,r[i].second}){dl.push_back(v&255);dh.push_back(v>>8);}auto dls=ans16_encode(dl,12),dhs=ans16_encode(dh,12);vector<uint8_t>o;put32(o,0x324c5354);put32(o,18444591);put32(o,cap);put32(o,n);put32(o,nm);vector<unsigned>lens(cap,1);unsigned ex=256;for(unsigned i=256;i<cap;i++){lens[i]=lens[r[i-256].first]+lens[r[i-256].second];ex+=lens[i];}put32(o,ex);for(auto&s:streams)put32(o,s.size());put32(o,dls.size());put32(o,dhs.size());o.insert(o.end(),dls.begin(),dls.end());o.insert(o.end(),dhs.begin(),dhs.end());for(auto&s:streams)o.insert(o.end(),s.begin(),s.end());uint64_t crc=0;size_t ci=0;for(;ci+8<=o.size();ci+=8){uint64_t q;memcpy(&q,o.data()+ci,8);crc=_mm_crc32_u64(crc,q);}for(;ci<o.size();ci++)crc=_mm_crc32_u8(crc,o[ci]);put32(o,crc);f=fopen("/work/lzfinal_archive.bin","wb");fwrite(o.data(),1,o.size(),f);fclose(f);cerr<<"cap="<<cap<<" tokens="<<n<<" matches="<<nm<<" literals="<<lc.size()<<" rawdict="<<(cap-256)*4<<" expanded="<<ex<<" streams=";for(auto&s:streams)cerr<<s.size()<<",";cerr<<" total="<<o.size()<<"\n";
f=fopen("/work/lzfinal_payload.h","w");fprintf(f,"static const unsigned char lzfinal_payload[]={\n");for(int i=0;i<o.size();i++){fprintf(f,"%u,",o[i]);if(i%32==31)fprintf(f,"\n");}fprintf(f,"};\n");fclose(f);}
